 1→export type Category =
 2→  | "Identity"
 3→  | "Brand Design"
 4→  | "Systems"
 5→  | "Event Design"
 6→  | "Motion"
 7→  | "Case Study"
 8→  | "Fractional CD"
 9→  | "Cutting Room Floor";
