11→export interface Project {
12→  slug: string;
13→  title: string;
14→  category: Category;
15→  desc: string;
16→  longDesc?: string;
17→  credits?: string;
18→  videoUrl?: string;
19→  color: string;
20→  year: string;
21→  featured?: boolean;
