  1→import { notFound } from "next/navigation";
  2→import Image from "next/image";
  3→import { PROJECTS, getProject, CASE_STUDIES } from "@/lib/projects";
  4→import { MetaTag } from "@/components/MetaTag";
  5→import { CaseStudySection } from "@/components/CaseStudySection";
  6→import { heroImage, detailImages } from "@/lib/images";
  7→import Link from "next/link";
  8→import type { Metadata } from "next";
  9→
 10→interface PageProps {
 11→  params: Promise<{ slug: string }>;
 12→}
 13→
 14→export async function generateStaticParams() {
 15→  return PROJECTS.map((p) => ({ slug: p.slug }));
 16→}
 17→
 18→export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
 19→  const { slug } = await params;
 20→  const project = getProject(slug);
 21→  if (!project) return {};
 22→  return {
 23→    title: project.title,
 24→    description: project.desc,
 25→  };
 26→}
 27→
 28→export default async function ProjectPage({ params }: PageProps) {
 29→  const { slug } = await params;
 30→  const project = getProject(slug);
 31→  if (!project) notFound();
 32→
 33→  const caseStudy = CASE_STUDIES[project.slug];
 34→  const hero = heroImage(project.slug);
 35→  const details = detailImages(project.slug);
 36→  const idx = PROJECTS.findIndex((p) => p.slug === project.slug);
 37→  const prev = idx > 0 ? PROJECTS[idx - 1] : null;
 38→  const next = idx < PROJECTS.length - 1 ? PROJECTS[idx + 1] : null;
 39→
 40→  return (
 41→    <div style={{ paddingTop: "var(--nav-h)" }}>
 42→      {/* Back link */}
 43→      <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "clamp(24px, 4vh, 40px) var(--pad) 0" }}>
 44→        <Link href="/work" className="link-muted" style={{ fontSize: 13, letterSpacing: "0.06em", textTransform: "uppercase", display: "inline-flex", alignItems: "center", gap: 8 }}>
 45→          <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.5">
 46→            <path d="M8 1L2 7L8 13" />
 47→          </svg>
 48→          All Work
 49→        </Link>
 50→      </div>
 51→
 52→      {/* Header */}
 53→      <div style={{ padding: "clamp(24px, 4vh, 40px) var(--pad) clamp(32px, 4vh, 60px)", maxWidth: "var(--max-w)", margin: "0 auto" }}>
 54→        <div style={{ display: "flex", gap: "clamp(32px, 4vw, 80px)", alignItems: "flex-start", flexWrap: "wrap" }}>
 55→          <div style={{ flex: "1 1 400px" }}>
 56→            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 16 }}>
 57→              <MetaTag label={project.category} />
 58→              <MetaTag label={project.year} />
 59→            </div>
 60→            <h1 style={{ fontSize: "clamp(32px, 4vw, 56px)", fontWeight: 400, letterSpacing: "-0.02em", color: "var(--text)", margin: "0 0 16px", lineHeight: 1.1 }}>
 61→              {project.title}
 62→            </h1>
 63→            <p style={{ fontSize: "clamp(16px, 1.4vw, 20px)", fontWeight: 400, color: "var(--muted)", lineHeight: 1.5, margin: 0, maxWidth: 480 }}>
 64→              {project.longDesc || project.desc}
 65→            </p>
 66→          </div>
 67→          <div style={{ flex: "0 0 200px", paddingTop: 40 }}>
 68→            {[
 69→              { label: "Role", value: "Brand Design Director" },
 70→              { label: "Year", value: project.year },
 71→              ...(project.credits ? [{ label: "Credits", value: project.credits }] : [{ label: "Scope", value: project.category }]),
 72→            ].map((item) => (
 73→              <div key={item.label} style={{ marginBottom: 20 }}>
 74→                <div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 400, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 4 }}>
 75→                  {item.label}
 76→                </div>
 77→                <div style={{ fontSize: 15, color: "var(--text)", fontWeight: 400, lineHeight: 1.4 }}>
 78→                  {item.value}
 79→                </div>
 80→              </div>
 81→            ))}
 82→          </div>
 83→        </div>
 84→      </div>
 85→
 86→      {/* Hero image -- natural aspect ratio, full width */}
 87→      {hero && (
 88→        <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "0 var(--pad)" }}>
 89→          <Image
 90→            src={hero}
 91→            alt={project.title}
 92→            width={2400}
 93→            height={1600}
 94→            style={{ width: "100%", height: "auto", borderRadius: "var(--img-radius)" }}
 95→            sizes="(max-width: 768px) 100vw, (max-width: 1400px) 90vw, 1400px"
 96→            priority
 97→          />
 98→        </div>
 99→      )}
100→
101→      {/* Video embed */}
102→      {project.videoUrl && (
103→        <div style={{ maxWidth: "var(--max-w)", margin: "40px auto 0", padding: "0 var(--pad)" }}>
104→          <div style={{ position: "relative", paddingBottom: "56.25%", height: 0, overflow: "hidden", borderRadius: "var(--img-radius)" }}>
105→            <iframe
106→              src={project.videoUrl}
107→              style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", border: 0 }}
108→              allow="autoplay; fullscreen; picture-in-picture"
109→              allowFullScreen
110→              title={project.title}
111→            />
112→          </div>
113→        </div>
114→      )}
115→
116→      {/* Case study or gallery -- single column, natural aspect ratios */}
117→      <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "0 var(--pad)" }}>
118→        {caseStudy ? (
119→          caseStudy.sections.map((section, si) => {
120→            // Compute cumulative offset from previous sections' image counts
121→            const offset = caseStudy.sections
122→              .slice(0, si)
123→              .reduce((sum, s) => sum + (s.images || 2), 0);
124→            const sectionImages = details.slice(offset, offset + (section.images || 2));
125→            return (
126→              <CaseStudySection key={si} section={section} title={project.title} images={sectionImages} />
127→            );
128→          })
129→        ) : details.length > 0 ? (
130→          <div style={{ display: "flex", flexDirection: "column", gap: 11, marginTop: 40 }}>
131→            {details.map((src, i) => (
132→              <Image
133→                key={i}
134→                src={src}
135→                alt={`${project.title} detail ${i + 1}`}
136→                width={2400}
137→                height={1600}
138→                style={{ width: "100%", height: "auto", borderRadius: "var(--img-radius)" }}
139→                sizes="(max-width: 768px) 100vw, (max-width: 1400px) 90vw, 1400px"
140→              />
141→            ))}
142→          </div>
143→        ) : null}
144→      </div>
145→
146→      {/* Prev/Next navigation */}
147→      <div style={{ maxWidth: "var(--max-w)", margin: "60px auto 0", padding: "0 var(--pad)", display: "flex", justifyContent: "space-between", borderTop: "1px solid var(--border)", paddingTop: 32 }}>
148→        {prev ? (
149→          <Link href={`/work/${prev.slug}`} className="hover-dim" style={{ fontSize: 16, color: "var(--text)" }}>
150→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Previous</span>
151→            {prev.title}
152→          </Link>
153→        ) : <div />}
154→        {next ? (
155→          <Link href={`/work/${next.slug}`} className="hover-dim" style={{ fontSize: 16, color: "var(--text)", textAlign: "right" }}>
156→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Next</span>
157→            {next.title}
158→          </Link>
159→        ) : <div />}
160→      </div>
161→
162→      <div style={{ height: 60 }} />
163→    </div>
164→  );
165→}
