 1→/** Image path helpers -- reads from auto-generated manifest */
 2→
 3→import { IMAGE_MANIFEST } from "./image-manifest";
 4→
 5→export function heroImage(slug: string): string | null {
 6→  return IMAGE_MANIFEST[slug]?.hero ?? null;
 7→}
 8→
 9→export function detailImages(slug: string): string[] {
10→  return IMAGE_MANIFEST[slug]?.details ?? [];
11→}
12→
13→export function detailCount(slug: string): number {
14→  return IMAGE_MANIFEST[slug]?.details.length ?? 0;
15→}
