 1→"use client";
 2→
 3→import Link from "next/link";
 4→import Image from "next/image";
 5→import { PlaceholderImage } from "./PlaceholderImage";
 6→import { MetaTag } from "./MetaTag";
 7→import { heroImage } from "@/lib/images";
 8→import type { Project } from "@/lib/types";
 9→import styles from "./GridCard.module.css";
10→
11→interface GridCardProps {
12→  project: Project;
13→  showText: boolean;
14→  height: number;
15→}
16→
17→export function GridCard({ project, showText, height }: GridCardProps) {
18→  const hero = heroImage(project.slug);
19→
20→  return (
21→    <Link href={`/work/${project.slug}`} className={styles.card}>
22→      {/* Image */}
23→      <div className={styles.imageContainer}>
24→        <div className={styles.clipWrapper}>
25→          <div className={styles.scaleWrapper}>
26→            {hero ? (
27→              <div style={{ position: "relative", width: "100%", height }}>
28→                <Image
29→                  src={hero}
30→                  alt={project.title}
31→                  fill
32→                  style={{ objectFit: "cover" }}
33→                  sizes="(max-width: 768px) 100vw, (max-width: 1400px) 66vw, 900px"
34→                />
35→              </div>
36→            ) : (
37→              <PlaceholderImage
38→                color={project.color}
39→                title={project.title}
40→                height={height}
41→                style={{ borderRadius: 0 }}
42→              />
43→            )}
44→          </div>
45→        </div>
46→
47→        {/* Image-only hover overlay */}
48→        {!showText && (
49→          <div className={styles.hoverOverlay}>
50→            <span className={styles.hoverTitle}>{project.title}</span>
51→          </div>
52→        )}
53→      </div>
54→
55→      {/* Text block with elevator metatags */}
56→      {showText && (
57→        <div className={styles.textBlock}>
58→          <h3 className={styles.title}>{project.title}</h3>
59→          <p className={styles.desc}>{project.desc}</p>
60→
61→          {/* Pentagram elevator metatags */}
62→          <div className={styles.metatagWrapper}>
63→            <div className={styles.metatagInner}>
64→              <MetaTag label={project.category} />
65→              <MetaTag label={project.year} />
66→            </div>
67→          </div>
68→        </div>
69→      )}
70→    </Link>
71→  );
72→}
