  1→.card {
  2→  cursor: pointer;
  3→  display: block;
  4→}
  5→
  6→.imageContainer {
  7→  border-radius: var(--img-radius);
  8→  overflow: hidden;
  9→  position: relative;
 10→}
 11→
 12→/* --- Scroll-driven card reveal --- */
 13→
 14→@keyframes cardReveal {
 15→  from {
 16→    clip-path: inset(0 0 100% 0);
 17→    opacity: 0;
 18→  }
 19→  to {
 20→    clip-path: inset(0 0 0% 0);
 21→    opacity: 1;
 22→  }
 23→}
 24→
 25→@keyframes cardScale {
 26→  from { transform: scale(1.06); }
 27→  to { transform: scale(1); }
 28→}
 29→
 30→@keyframes textFadeIn {
 31→  from {
 32→    opacity: 0;
 33→    transform: translateY(10px);
 34→  }
 35→  to {
 36→    opacity: 1;
 37→    transform: translateY(0);
 38→  }
 39→}
 40→
 41→.clipWrapper {
 42→  animation: cardReveal linear both;
 43→  animation-timeline: view();
 44→  animation-range: entry 0% entry 60%;
 45→}
 46→
 47→.scaleWrapper {
 48→  animation: cardScale linear both;
 49→  animation-timeline: view();
 50→  animation-range: entry 0% entry 90%;
 51→}
 52→
 53→/* Image-only hover overlay */
 54→.hoverOverlay {
 55→  position: absolute;
 56→  bottom: 0;
 57→  left: 0;
 58→  right: 0;
 59→  top: 0;
 60→  border-radius: var(--img-radius);
 61→  display: flex;
 62→  align-items: flex-end;
 63→  padding: 20px;
 64→  background: transparent;
 65→  opacity: 0;
 66→  transition: all 400ms var(--ease);
 67→  pointer-events: none;
 68→}
 69→
 70→.card:hover .hoverOverlay {
 71→  background: linear-gradient(to top, rgba(0, 0, 0, 0.5) 0%, transparent 60%);
 72→  opacity: 1;
 73→}
 74→
 75→.hoverTitle {
 76→  color: #fff;
 77→  font-size: 14px;
 78→  font-weight: 400;
 79→  letter-spacing: 0.02em;
 80→  transform: translateY(8px);
 81→  transition: transform 400ms var(--ease-out);
 82→}
 83→
 84→.card:hover .hoverTitle {
 85→  transform: translateY(0);
 86→}
 87→
 88→/* Text block */
 89→.textBlock {
 90→  margin-top: 14px;
 91→  padding-bottom: 38px;
 92→  position: relative;
 93→  animation: textFadeIn linear both;
 94→  animation-timeline: view();
 95→  animation-range: entry 15% entry 55%;
 96→}
 97→
 98→.title {
 99→  font-size: 16px;
100→  font-weight: 400;
101→  margin: 0 0 3px;
102→  color: var(--text);
103→  letter-spacing: normal;
104→  line-height: 1.35;
105→}
106→
107→.desc {
108→  font-size: 15px;
109→  font-weight: 400;
110→  margin: 0;
111→  color: var(--muted);
112→  letter-spacing: normal;
113→  line-height: 1.35;
114→}
115→
116→/* Elevator metatags */
117→.metatagWrapper {
118→  position: absolute;
119→  bottom: 0;
120→  left: 0;
121→  right: 0;
122→  height: 30px;
123→  overflow: hidden;
124→}
125→
126→.metatagInner {
127→  display: flex;
128→  flex-wrap: wrap;
129→  gap: 8px;
130→  transform: translateY(-110%);
131→  opacity: 0;
132→  transition:
133→    transform 350ms var(--ease),
134→    opacity 250ms var(--ease);
135→}
136→
137→.card:hover .metatagInner {
138→  transform: translateY(0);
139→  opacity: 1;
140→  transition:
141→    transform 350ms var(--ease-out),
142→    opacity 250ms var(--ease-out);
143→}
144→
145→/* Image desaturation */
146→.imageDefault {
147→  filter: saturate(0.85);
148→  transition: filter 400ms var(--ease);
149→}
150→
151→.card:hover .imageDefault {
152→  filter: saturate(1) brightness(1.02);
153→}
154→
155→/* Fallback: browsers without scroll-driven animation support */
156→@supports not (animation-timeline: view()) {
157→  .clipWrapper {
158→    clip-path: none;
159→    opacity: 1;
160→    animation: none;
161→  }
162→  .scaleWrapper {
163→    transform: none;
164→    animation: none;
165→  }
166→  .textBlock {
167→    opacity: 1;
168→    transform: none;
169→    animation: none;
170→  }
171→}
172→
173→/* Accessibility: reduced motion */
174→@media (prefers-reduced-motion: reduce) {
175→  .clipWrapper,
176→  .scaleWrapper,
177→  .textBlock {
178→    animation: none;
179→    clip-path: none;
180→    opacity: 1;
181→    transform: none;
182→  }
183→}
184→

  1→/* --- Design Tokens as CSS Custom Properties --- */
  2→:root {
  3→  --bg: #EEEEEC;
  4→  --text: #1A1A1A;
  5→  --muted: #767676;
  6→  --muted-light: #999999;
  7→  --accent: #D4FF00;
  8→  --border: #E8E8E6;
  9→  --grid-line: rgba(0,0,0,0.055);
 10→  --grid-line-hover: rgba(0,0,0,0.08);
 11→  --font: 'Inter', -apple-system, 'Helvetica Neue', Helvetica, sans-serif;
 12→  --ease: cubic-bezier(0.33, 1, 0.68, 1);
 13→  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
 14→  --pad: clamp(20px, 4vw, 80px);
 15→  --max-w: 1400px;
 16→  --nav-h: 72px;
 17→  --img-radius: 6px;
 18→  --row-gap: 24px;
 19→}
 20→
 21→/* --- Resets --- */
 22→*, *::before, *::after {
 23→  box-sizing: border-box;
 24→}
 25→
 26→html {
 27→  scroll-behavior: smooth;
 28→}
 29→
 30→body {
 31→  margin: 0;
 32→  background: var(--bg);
 33→  color: var(--text);
 34→  font-family: var(--font);
 35→  -webkit-font-smoothing: antialiased;
 36→  -moz-osx-font-smoothing: grayscale;
 37→}
 38→
 39→h1, h2, h3, h4, h5, h6, p {
 40→  margin: 0;
 41→  font-weight: 400;
 42→}
 43→
 44→button {
 45→  border: none;
 46→  font: inherit;
 47→  cursor: pointer;
 48→  background: none;
 49→}
 50→
 51→a {
 52→  color: inherit;
 53→  text-decoration: none;
 54→}
 55→
 56→/* --- Keyframes --- */
 57→@keyframes lineReveal {
 58→  from { transform: translateX(-50%) scaleY(0); }
 59→  to { transform: translateX(-50%) scaleY(1); }
 60→}
 61→
 62→@keyframes fadeSlideUp {
 63→  from { opacity: 0; transform: translateY(16px); }
 64→  to { opacity: 1; transform: translateY(0); }
 65→}
 66→
 67→@keyframes pageEnter {
 68→  from { opacity: 0; }
 69→  to { opacity: 1; }
 70→}
 71→
 72→main {
 73→  animation: pageEnter 400ms var(--ease-out) both;
 74→}
 75→
 76→/* --- Hover utilities (for server components that can't use JS hover) --- */
 77→.link-muted {
 78→  color: var(--muted-light);
 79→  transition: color 200ms var(--ease);
 80→}
 81→.link-muted:hover {
 82→  color: var(--text);
 83→}
 84→
 85→.hover-dim {
 86→  transition: opacity 200ms var(--ease);
 87→}
 88→.hover-dim:hover {
 89→  opacity: 0.6;
 90→}
 91→
 92→/* --- Responsive --- */
 93→@media (max-width: 768px) {
 94→  .grid-pair { grid-template-columns: 1fr !important; }
 95→  .grid-triple { grid-template-columns: 1fr !important; }
 96→}
 97→
 98→/* --- Accessibility --- */
 99→:focus { outline: none; }
100→:focus-visible {
101→  outline: 2px solid rgba(0, 0, 0, 0.3);
102→  outline-offset: 2px;
103→}
104→button:focus:not(:focus-visible),
105→a:focus:not(:focus-visible) { outline: none; }
106→
107→@media (prefers-reduced-motion: reduce) {
108→  html { scroll-behavior: auto; }
109→  *, *::before, *::after {
110→    animation-duration: 0.01ms !important;
111→    animation-iteration-count: 1 !important;
112→    transition-duration: 0.01ms !important;
113→  }
114→}
