 3→import { useState, useEffect } from "react";
 4→
 5→export function ScrollProgress() {
 6→  const [progress, setProgress] = useState(0);
 7→
 8→  useEffect(() => {
 9→    const handler = () => {
10→      const pct = window.scrollY / (document.documentElement.scrollHeight - window.innerHeight);
11→      setProgress(Math.min(1, Math.max(0, pct)));
12→    };
13→    window.addEventListener("scroll", handler, { passive: true });
14→    return () => window.removeEventListener("scroll", handler);
15→  }, []);
16→
17→  if (progress < 0.01) return null;
18→
19→  return (
20→    <div style={{ position: "fixed", top: 0, left: 0, right: 0, height: 2, zIndex: 200 }}>
21→      <div
22→        style={{
23→          height: "100%",
24→          background: "var(--text)",
25→          opacity: 0.15,
26→          transform: `scaleX(${progress})`,
27→          transformOrigin: "left",
28→          transition: "transform 100ms linear",
29→        }}
30→      />
31→    </div>
32→  );
33→}
