199→async function processImage(srcPath, destPath, label) {
200→  if (!isSupported(srcPath)) {
201→    console.log(`  SKIP (unsupported format): ${basename(srcPath)}`);
202→    return false;
203→  }
204→
205→  if (DRY_RUN) {
206→    console.log(`  DRY-RUN: ${basename(srcPath)} -> ${destPath}`);
207→    return true;
208→  }
209→
210→  try {
211→    const image = sharp(srcPath);
212→    const metadata = await image.metadata();
213→    const needsResize = metadata.width > MAX_WIDTH;
214→
215→    let pipeline = image;
216→    if (needsResize) {
217→      pipeline = pipeline.resize({ width: MAX_WIDTH, withoutEnlargement: true });
218→    }
219→
220→    await pipeline
221→      .jpeg({ quality: JPEG_QUALITY, mozjpeg: true })
222→      .toFile(destPath);
223→
224→    const srcStat = await stat(srcPath);
225→    const destStat = await stat(destPath);
226→    const savings = Math.round((1 - destStat.size / srcStat.size) * 100);
227→    const dims = needsResize ? `${metadata.width} -> ${MAX_WIDTH}w` : `${metadata.width}w (no resize)`;
228→
229→    console.log(`  OK: ${label} [${dims}, ${savings > 0 ? `-${savings}%` : `+${Math.abs(savings)}%`}]`);
230→    return true;
231→  } catch (err) {
232→    console.error(`  ERROR: ${label} -- ${err.message}`);
233→    return false;
234→  }
235→}
