237→async function processProject(slug, config) {
238→  console.log(`\n--- ${slug} ---`);
239→  const srcDir = join(SRC_ROOT, config.src);
240→  const destDir = join(DEST_ROOT, slug);
241→  await ensureDir(destDir);
242→
243→  let count = 0;
244→
245→  // Hero image
246→  const heroSrc = join(srcDir, config.hero);
247→  const heroDest = join(destDir, "hero.jpg");
248→  if (await processImage(heroSrc, heroDest, `hero (${config.hero})`)) count++;
249→
250→  // Detail images
251→  for (let i = 0; i < config.details.length; i++) {
252→    const filename = config.details[i];
253→    const srcPath = join(srcDir, filename);
254→    const num = String(i + 1).padStart(2, "0");
255→    const destPath = join(destDir, `detail-${num}.jpg`);
256→    if (await processImage(srcPath, destPath, `detail-${num} (${basename(filename)})`)) count++;
257→  }
258→
259→  console.log(`  Total: ${count} images`);
260→  return count;
261→}
