263→async function processPortrait() {
264→  console.log(`\n--- portrait ---`);
265→  const srcPath = join(SRC_ROOT, PORTRAIT.src);
266→  const destDir = join(DEST_ROOT, "about");
267→  await ensureDir(destDir);
268→  const destPath = join(DEST_ROOT, PORTRAIT.dest);
269→  await processImage(srcPath, destPath, "portrait");
270→}
