272→async function main() {
273→  console.log("=== Image Optimization Pipeline ===");
274→  console.log(`Source: ${SRC_ROOT}`);
275→  console.log(`Dest:   ${DEST_ROOT}`);
276→  console.log(`Max width: ${MAX_WIDTH}px, JPEG quality: ${JPEG_QUALITY}`);
277→  if (DRY_RUN) console.log("*** DRY RUN -- no files will be written ***\n");
278→
279→  let totalImages = 0;
280→
281→  for (const [slug, config] of Object.entries(IMAGE_MAP)) {
282→    totalImages += await processProject(slug, config);
283→  }
284→
285→  await processPortrait();
286→  totalImages++;
287→
288→  console.log(`\n=== Done: ${totalImages} images processed ===`);
289→}
